begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is(has_table_privilege('anon','private.registration_intents','SELECT,INSERT,UPDATE,DELETE'),false,'No anonymous raw intent access');
select is(has_table_privilege('authenticated','private.registration_intents','SELECT,INSERT,UPDATE,DELETE'),false,'No authenticated raw intent access');
select is(has_column_privilege('authenticated','public.profiles','username','UPDATE'),false,'No client username modification');
select throws_ok($$select public.prepare_registration('valid_name','fixture@example.test','2000-02-29',repeat('a',64))$$,'42501','Trusted registration preparation required.','Direct Data API cannot bypass capability');
insert into private.event_cover_config(singleton,operation_key_hash) values(true,encode(extensions.digest('synthetic-registration-capability','sha256'),'hex'))
 on conflict(singleton) do update set operation_key_hash=excluded.operation_key_hash;
select set_config('request.headers','{"x-rollcall-cover-key":"synthetic-registration-capability"}',true);
create temporary table registration_fixture as select gen_random_uuid() id,public.prepare_registration('Unique_Player','fixture@example.test','2000-02-29',repeat('a',64)) intent;
select is((select intent->>'status' from registration_fixture),'ready','Preparation succeeds');
select is(public.prepare_registration('UNIQUE_PLAYER','other@example.test','2000-02-29',repeat('b',64))->>'status','duplicate','Case-insensitive pending username uniqueness');
select throws_ok($$select public.prepare_registration('invalid_date','fixture@example.test','2001-02-29',repeat('a',64))$$,'22023','Invalid date of birth.','Invalid calendar date rejected by SQL');
insert into auth.users(id,email,raw_user_meta_data) select id,'fixture@example.test',jsonb_build_object('rollcall_registration_token',intent->>'token') from registration_fixture;
select is((select count(*)::int from public.profiles where id=(select id from registration_fixture)),1,'One profile initialized before confirmation');
select is((select username from public.profiles where id=(select id from registration_fixture)),'Unique_Player','Validated username casing persisted');
select is((select date_of_birth::text from private.profile_private where profile_id=(select id from registration_fixture)),'2000-02-29','Full date persisted privately');
select is((select raw_user_meta_data from auth.users where id=(select id from registration_fixture)),'{}'::jsonb,'Transport ticket removed from Auth metadata');
update auth.users set raw_user_meta_data='{"dateOfBirth":"2000-02-29","date_of_birth":"2000-02-29","rollcall_registration_token":"consumed","theme":"dark"}' where id=(select id from registration_fixture);
select is((select raw_user_meta_data from auth.users where id=(select id from registration_fixture)),'{"theme":"dark"}'::jsonb,'Auth metadata rewrites cannot persist DOB or consumed tickets');
select is((select count(*)::int from private.registration_intents where claimed_account=(select id from registration_fixture)),0,'Consumed intent deleted');
select is((select count(*)::int from private.account_roles where profile_id=(select id from registration_fixture)),0,'Registration cannot create privileged roles');
select is(public.prepare_registration('UNIQUE_PLAYER','other@example.test','2000-02-29',repeat('c',64))->>'status','duplicate','Persisted username cannot be claimed again');
select throws_ok($$insert into auth.users(id,email,raw_user_meta_data) values(gen_random_uuid(),'bypass@example.test','{}')$$,'22023','Use the RollCall registration form.','Unprepared signup rejected');
create temporary table invalid_ticket as select public.prepare_registration('email_bound','bound@example.test','2000-02-29',repeat('d',64)) intent;
select throws_ok($$insert into auth.users(id,email,raw_user_meta_data) select gen_random_uuid(),'wrong@example.test',jsonb_build_object('rollcall_registration_token',intent->>'token') from invalid_ticket$$,'22023','Use the RollCall registration form.','Ticket cannot be used for another email');
update private.registration_intents set expires_at=clock_timestamp()-interval '1 second' where username='email_bound';
select throws_ok($$insert into auth.users(id,email,raw_user_meta_data) select gen_random_uuid(),'bound@example.test',jsonb_build_object('rollcall_registration_token',intent->>'token') from invalid_ticket$$,'22023','Use the RollCall registration form.','Expired ticket cannot initialize an account');
select throws_ok($$insert into auth.users(id,email,raw_user_meta_data) select gen_random_uuid(),'fixture@example.test',jsonb_build_object('rollcall_registration_token',intent->>'token') from registration_fixture$$,'22023','Use the RollCall registration form.','Consumed ticket cannot be replayed');
insert into private.registration_attempts values(repeat('e',64),clock_timestamp(),20);
select is(public.prepare_registration('rate_limited','limited@example.test','2000-02-29',repeat('e',64))->>'status','limited','Rate limit produces a durable result, not a rolled-back error');
select is((select attempts from private.registration_attempts where fingerprint=repeat('e',64)),21,'Denied attempt is persisted');
select throws_ok($$update private.profile_private set birth_year=1999 where profile_id=(select id from registration_fixture)$$,'22023','Birth year must match the private registration date.','Legacy age edit cannot contradict full date');
update auth.users set email_confirmed_at=now() where id=(select id from registration_fixture);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from registration_fixture),'role','authenticated')::text,true);
select is(public.get_my_profile()->>'hasDateOfBirth','true','Own profile communicates only presence');
select ok(not(public.get_my_profile() ? 'dateOfBirth') and not(public.get_my_profile() ? 'date_of_birth'),'Own profile DTO omits full date');
select ok(not(public.public_profile((select id from registration_fixture))::text like '%2000-02-29%'),'Public profile omits date');
select * from finish();
rollback;
